begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','confirm_owned_storefront_handle',array['text','uuid']);
insert into auth.users(id,email) values ('24000000-0000-4000-8000-000000000001','sf-a@example.invalid'),('24000000-0000-4000-8000-000000000002','sf-b@example.invalid');
insert into public.organizers(id,display_name) values ('24000000-0000-4000-8000-000000000001','Organizer A'),('24000000-0000-4000-8000-000000000002','Organizer B');
insert into storage.objects(id,bucket_id,name,metadata,user_metadata) values
 ('24000000-0000-4000-8000-000000000011','organizer-media','24000000-0000-4000-8000-000000000001/24000000-0000-4000-8000-000000000011.png','{"size":100,"mimetype":"image/png"}','{"organizer_id":"24000000-0000-4000-8000-000000000001"}'),
 ('24000000-0000-4000-8000-000000000012','organizer-media','24000000-0000-4000-8000-000000000002/24000000-0000-4000-8000-000000000012.png','{"size":100,"mimetype":"image/png"}','{"organizer_id":"24000000-0000-4000-8000-000000000002"}');
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.confirm_owned_storefront_handle('events','24000000-0000-4000-8000-000000000011')$$,'P0001','HANDLE_INVALID','Reserved rejected');
select throws_ok($$select public.confirm_owned_storefront_handle('a--b','24000000-0000-4000-8000-000000000011')$$,'P0001','HANDLE_INVALID','Invalid rejected');
select throws_ok($$select public.confirm_owned_storefront_handle('dj-marcus','24000000-0000-4000-8000-000000000012')$$,'P0001','LOGO_NOT_OWNED','Foreign logo rejected');
select lives_ok($$select public.confirm_owned_storefront_handle(' DJ-Marcus ','24000000-0000-4000-8000-000000000011')$$,'Atomic normalized claim');
select is((select handle from public.organizers),'dj-marcus','Normalized handle');
select ok((select handle_confirmed_at is not null from public.organizers),'Server confirmation timestamp');
select is((select storefront_status from public.organizers),'draft','Draft by default');
select lives_ok($$select public.confirm_owned_storefront_handle('dj-marcus','24000000-0000-4000-8000-000000000011')$$,'Same claim safely retries');
select throws_ok($$select public.confirm_owned_storefront_handle('another-name','24000000-0000-4000-8000-000000000011')$$,'P0001','HANDLE_IMMUTABLE','Cannot rename handle');
select throws_ok($$update public.organizers set handle='changed'$$,'42501',null,'Direct writes denied');
select lives_ok($$select public.save_owned_organizer_settings('New name',null,(select updated_at from public.organizers))$$,'Canonical profile rename');
select is((select handle from public.organizers),'dj-marcus','Name never changes URL');
reset role;
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.confirm_owned_storefront_handle('dj-marcus','24000000-0000-4000-8000-000000000012')$$,'P0001','HANDLE_TAKEN','Duplicate rejected');
reset role;
set local role anon;
select is(public.get_public_organizer_storefront('dj-marcus'),null::jsonb,'Draft not exposed');
select is(public.get_public_organizer_storefront('does-not-exist'),null::jsonb,'Absent matches draft');
select ok(not public.storefront_handle_available('DJ-Marcus'),'Claim availability derives database');
select throws_ok($$select * from public.organizers$$,'42501',null,'No organizer row access');
select throws_ok($$select public.confirm_owned_storefront_handle('steal','24000000-0000-4000-8000-000000000011')$$,'42501',null,'Anonymous cannot claim');
reset role;
select throws_ok($$update public.organizers set handle='privileged-change' where handle='dj-marcus'$$,'P0001','HANDLE_IMMUTABLE','Trigger also protects privileged accidental rename');
update public.organizers set storefront_logo_asset_id=null where handle='dj-marcus';
select set_config('request.jwt.claim.sub','24000000-0000-4000-8000-000000000001',true);
select public.confirm_owned_storefront_handle('dj-marcus','24000000-0000-4000-8000-000000000011');
select is((select storefront_logo_asset_id from public.organizers where handle='dj-marcus'),null::uuid,'Claim retry cannot overwrite subsequent branding');
select * from finish(); rollback;
